// Synthetic replica of react-native-svg@15 sources: TSX shipped as the
// "react-native" entry, registering native host components for Svg and Path
// off the React Native default export.
import ReactNative from "react-native";

const requireNativeComponent =
  (ReactNative as { requireNativeComponent?: (name: string) => unknown }).requireNativeComponent ??
  ((name: string) => name);

const SvgNativeComponent = requireNativeComponent("RNSVGSvgView");
const PathNativeComponent = requireNativeComponent("RNSVGPath");

export const SVG_OK = "SVG_OK";

export function Svg(props: { children?: unknown }) {
  return <SvgNativeComponent>{props.children}</SvgNativeComponent>;
}

export function Path(props: { d?: string }) {
  return <PathNativeComponent d={props.d} />;
}

export default Svg;
